CREATE TABLE users (email TEXT PRIMARY KEY, password_hash TEXT NOT NULL, role TEXT NOT NULL);
CREATE TABLE destinations (name TEXT PRIMARY KEY, region TEXT NOT NULL);
CREATE TABLE vehicles (registration_number TEXT PRIMARY KEY, model TEXT NOT NULL, type TEXT NOT NULL, max_load_capacity DOUBLE PRECISION NOT NULL, odometer DOUBLE PRECISION NOT NULL, acquisition_cost DOUBLE PRECISION NOT NULL, status TEXT NOT NULL DEFAULT 'Available');
CREATE TABLE drivers (license_number TEXT PRIMARY KEY, name TEXT NOT NULL, license_category TEXT NOT NULL, license_expiry_date TEXT NOT NULL, contact_number TEXT NOT NULL, safety_score DOUBLE PRECISION NOT NULL DEFAULT 100, status TEXT NOT NULL DEFAULT 'Available');
CREATE TABLE trips (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_name TEXT NOT NULL REFERENCES destinations(name), destination_name TEXT NOT NULL REFERENCES destinations(name), vehicle_reg TEXT NOT NULL REFERENCES vehicles(registration_number), driver_license TEXT NOT NULL REFERENCES drivers(license_number), cargo_weight DOUBLE PRECISION NOT NULL, planned_distance DOUBLE PRECISION NOT NULL, revenue DOUBLE PRECISION NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Draft');
CREATE TABLE maintenance_logs (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vehicle_reg TEXT NOT NULL REFERENCES vehicles(registration_number), description TEXT NOT NULL, cost DOUBLE PRECISION NOT NULL, start_date TEXT NOT NULL, end_date TEXT, status TEXT NOT NULL DEFAULT 'Open');
CREATE TABLE expenses (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trip_id INTEGER NOT NULL REFERENCES trips(id) ON DELETE CASCADE, type TEXT NOT NULL, liters DOUBLE PRECISION, cost DOUBLE PRECISION NOT NULL, date TEXT NOT NULL);
